import re
FIELD_PATTERN = '(?x)\n^                                               # Start of line anchor\n(?:\n    # Branch 1: Canonical block\n    (?P<canonical>\n        ^```(?:old|new)\\r?\\n              # Opening fence\n        (?:(?P<canonical_body>.*?)?\\r?\\n)? # Optional body + EOL\n        ^```[ \\t]*(?:\\r?\\n|$)                       # Exact closing fence\n    )\n    |\n    # Branch 2: Labeled field branch\n    (?P<labeledfield>\n        ^                                # Start of line\n        (?P<label>                       # Capture label\n            OLD|OLD_TEXT|EXACT_OLD_SUBSTRING|BEFORE|\n            NEW|NEW_TEXT|REPLACEMENT_SUBSTRING|AFTER\n        )\n        (?::)?                           # Optional colon\n        [ \\t]*\\r?\\n                      # End of label line\n        (?:[ \\t]*\\r?\\n)*                 # Optional blank metadata lines\n        ^```(?:tsx|ts|jsx|js|javascript)? # Generic opening fence\n        (?P<opening>\\r?\\n)               # Capture ONLY the EOL\n        (?P<body_content>.*?)            # Capture source body (non-greedy)\n        (?P<closing>^```[ \\t]*(?:\\r?\\n|$))   # Exact closing fence + optional EOL/EOF\n    )\n)\n'
